1	import type { DehydratedState } from "@tanstack/react-query";
2	import { createHead } from "@unhead/react/client";
3	import { createRoot, hydrateRoot } from "react-dom/client";
4	import {
5	  createBrowserRouter,
6	  matchRoutes,
7	  type RouteObject,
8	} from "react-router";
9	import "vite/modulepreload-polyfill";
10	import config from "virtual:zudoku-config";
11	import { setupCookieSync } from "../lib/authentication/cookie-sync.js";
12	import { SESSION_ENDPOINT_PATH } from "../lib/authentication/cookies.js";
13	import { authState } from "../lib/authentication/state.js";
14	import { BootstrapClient } from "../lib/components/Bootstrap.js";
15	import { joinUrl } from "../lib/util/joinUrl.js";
16	import { getRoutesByConfig, shikiReady } from "./main.js";
17	
18	if (import.meta.env.ZUDOKU_HAS_SERVER) {
19	  setupCookieSync(authState, joinUrl(config.basePath, SESSION_ENDPOINT_PATH));
20	}
21	
22	const routes = getRoutesByConfig(config);
23	// biome-ignore lint/style/noNonNullAssertion: We know the root element exists
24	const root = document.getElementById("root")!;
25	const head = createHead();
26	
27	declare global {
28	  interface Window {
29	    ZUDOKU_VERSION: string;
30	    ZUDOKU_DATA?: DehydratedState;
31	  }
32	}
33	
34	window.ZUDOKU_VERSION = process.env.ZUDOKU_VERSION ?? "unknown";
35	
36	if (process.env.SENTRY_DSN) {
37	  void import("./sentry.js").then((mod) => {
38	    mod.initSentry({ dsn: process.env.SENTRY_DSN as string });
39	  });
40	}
41	
42	if (root.childElementCount > 0) {
43	  void hydrate(routes);
44	} else {
45	  void render(routes);
46	}
47	
48	if (import.meta.env.IS_ZUPLO) {
49	  // biome-ignore lint/suspicious/noConsole: Logging allowed here
50	  console.log(
51	    `%cPowered by Zuplo v${window.ZUDOKU_VERSION}`,
52	    [
53	      "color: #Df0097",
54	      "line-height: 50px",
55	      "font-weight: bolder",
56	      "font-size: 15px",
57	      "text-align: center",
58	      "letter-spacing: 5px",
59	    ].join(" ;"),
60	  );
61	} else {
62	  // biome-ignore lint/suspicious/noConsole: Logging allowed here
63	  console.log(
64	    `%cZUDOKU%c by Zuplo v${window.ZUDOKU_VERSION}`,
65	    [
66	      "color: #FF00BD",
67	      "line-height: 50px",
68	      "font-weight: bolder",
69	      "font-size: 30px",
70	      "-webkit-text-stroke-width: 1px",
71	      "-webkit-text-stroke-color: #FF00BD",
72	      "text-transform: uppercase",
73	      "text-align: center",
74	      "letter-spacing: 5px",
75	    ].join(" ;"),
76	    [
77	      "color: #Df0097",
78	      "line-height: 50px",
79	      "font-weight: bolder",
80	      "font-size: 15px",
81	      "text-align: center",
82	      "letter-spacing: 5px",
83	    ].join(" ;"),
84	  );
85	  // biome-ignore lint/suspicious/noConsole: Logging allowed here
86	  console.log("» Learn more about Zudoku https://zudoku.dev");
87	}
88	
89	async function hydrateLazyRoutes(routes: RouteObject[]) {
90	  const path = window.location.pathname;
91	  const lazyMatches = matchRoutes(routes, path, config.basePath)?.filter(
92	    (m) => m.route.lazy,
93	  );
94	
95	  if (lazyMatches?.length) {
96	    await Promise.all(
97	      lazyMatches.map(async (m) => {
98	        if (typeof m.route.lazy !== "function") return;
99	
100	        const routeModule = await m.route.lazy();
101	        Object.assign(m.route, { ...routeModule, lazy: undefined });
102	      }),
103	    );
104	  }
105	}
106	
107	function render(routes: RouteObject[]) {
108	  const router = createBrowserRouter(routes, {
109	    basename: config.basePath,
110	  });
111	  createRoot(root).render(<BootstrapClient router={router} head={head} />);
112	}
113	
114	async function hydrate(routes: RouteObject[]) {
115	  await Promise.all([hydrateLazyRoutes(routes), shikiReady]);
116	
117	  const router = createBrowserRouter(routes, {
118	    basename: config.basePath,
119	  });
120	
121	  hydrateRoot(root, <BootstrapClient hydrate router={router} head={head} />);
122	}
123	
124	// Reload on chunk preload failures to recover from version skew.
125	// Throttled so a non-recoverable error (e.g. auth-gated chunk 401) doesn't loop infinitely.
126	// https://vite.dev/guide/build.html#load-error-handling
127	window.addEventListener("vite:preloadError", (e) => {
128	  e.preventDefault();
129	  const last = Number(sessionStorage.getItem("zudoku:preload-reload-ts") ?? 0);
130	  if (Date.now() - last < 30_000) return;
131	  sessionStorage.setItem("zudoku:preload-reload-ts", String(Date.now()));
132	  window.location.reload();
133	});
