1	import type { RouteObject } from "react-router";
2	import type { HighlighterCore } from "shiki";
3	import { configuredApiKeysPlugin } from "virtual:zudoku-api-keys-plugin";
4	import {
5	  configuredApiCatalogPlugins,
6	  configuredApiPlugins,
7	} from "virtual:zudoku-api-plugins";
8	import { configuredAuthProvider } from "virtual:zudoku-auth";
9	import { configuredCustomPagesPlugin } from "virtual:zudoku-custom-pages-plugin";
10	import { configuredDocsPlugin } from "virtual:zudoku-docs-plugin";
11	import {
12	  configuredHeaderNavigation,
13	  configuredNavigation,
14	  configuredNavigationRules,
15	} from "virtual:zudoku-navigation";
16	import { configuredSearchPlugin } from "virtual:zudoku-search-plugin";
17	import "virtual:zudoku-theme.css";
18	import { Zudoku } from "zudoku/components";
19	import { Outlet } from "zudoku/router";
20	import type { ZudokuConfig } from "../config/config.js";
21	import { authState } from "../lib/authentication/state.js";
22	import { BuildCheck } from "../lib/components/BuildCheck.js";
23	import { Meta } from "../lib/components/Meta.js";
24	import "./main.css";
25	import { StatusPage } from "../lib/components/StatusPage.js";
26	import "./polyfills.js";
27	import { isNavigationPlugin } from "../lib/core/plugins.js";
28	import { RouteGuard } from "../lib/core/RouteGuard.js";
29	import type { ZudokuContextOptions } from "../lib/core/ZudokuContext.js";
30	import { RouterError } from "../lib/errors/RouterError.js";
31	import { ZuploEnv } from "./env.js";
32	import { processRoutes } from "./processRoutes.js";
33	import { createRedirectRoutes } from "./utils/createRedirectRoutes.js";
34	import {
35	  warnInlineProtectedRoutes,
36	  wrapProtectedRoutes,
37	} from "./wrapProtectedRoutes.js";
38	
39	export const shikiReady: Promise<HighlighterCore> =
40	  import("../lib/shiki.js").then(async ({ highlighterPromise }) => {
41	    const highlighter = await highlighterPromise;
42	    const { registerShiki } = await import("virtual:zudoku-shiki-register");
43	    await registerShiki(highlighter);
44	    return highlighter;
45	  });
46	
47	export const convertZudokuConfigToOptions = (
48	  config: ZudokuConfig,
49	): ZudokuContextOptions => {
50	  return {
51	    basePath: config.basePath,
52	    canonicalUrlOrigin: config.canonicalUrlOrigin,
53	    aiAssistants: config.aiAssistants,
54	    protectedRoutes: config.protectedRoutes,
55	    site: {
56	      ...config.site,
57	      showPoweredBy:
58	        ZuploEnv.buildConfig?.entitlements.devPortalZuploBranding ??
59	        config.site?.showPoweredBy,
60	      logo: config.site?.logo,
61	    },
62	    slots: config.slots,
63	    metadata: {
64	      favicon: "https://cdn.zudoku.dev/logos/favicon.svg",
65	      title: "%s - Zudoku",
66	      ...config.metadata,
67	    },
68	    header: {
69	      navigation: configuredHeaderNavigation,
70	      placements: config.header?.placements,
71	      themeSwitcher: config.header?.themeSwitcher,
72	    },
73	    navigation: configuredNavigation,
74	    navigationRules: configuredNavigationRules,
75	    mdx: config.mdx,
76	    plugins: [
77	      ...(configuredAuthProvider ? [configuredAuthProvider] : []),
78	      ...(configuredDocsPlugin ? [configuredDocsPlugin] : []),
79	      ...configuredApiPlugins,
80	      ...(configuredSearchPlugin ? [configuredSearchPlugin] : []),
81	      ...(configuredApiKeysPlugin ? [configuredApiKeysPlugin] : []),
82	      ...(configuredCustomPagesPlugin ? [configuredCustomPagesPlugin] : []),
83	      ...configuredApiCatalogPlugins,
84	      ...(config.plugins ?? []),
85	    ],
86	    syntaxHighlighting: {
87	      highlighterPromise: shikiReady,
88	      themes: config.syntaxHighlighting?.themes,
89	    },
90	  };
91	};
92	
93	export const getRoutesByOptions = (
94	  options: ZudokuContextOptions,
95	  enableStatusPages = true,
96	) => {
97	  const allPlugins = [
98	    ...(options.plugins ?? []),
99	    ...(options.authentication ? [options.authentication] : []),
100	  ];
101	
102	  const routes = allPlugins
103	    .flatMap((plugin) => (isNavigationPlugin(plugin) ? plugin.getRoutes() : []))
104	    .concat(
105	      enableStatusPages
106	        ? [400, 404, 500].map((statusCode) => ({
107	            path: `/${statusCode}`,
108	            element: <StatusPage statusCode={statusCode} />,
109	          }))
110	        : [],
111	    )
112	    .concat([{ path: "*", element: <StatusPage statusCode={404} /> }])
113	    .map((route) => ({
114	      ...route,
115	      errorElement: <RouterError className="w-full m-0" />,
116	    }));
117	
118	  // @TODO Detect conflicts in routes and log warning
119	
120	  return routes;
121	};
122	
123	export const getRoutesByConfig = (config: ZudokuConfig): RouteObject[] => {
124	  const options = convertZudokuConfigToOptions(config);
125	  const routes = getRoutesByOptions(
126	    options,
127	    import.meta.env.IS_ZUPLO || config.enableStatusPages,
128	  );
129	
130	  if (import.meta.env.DEV && typeof window !== "undefined") {
131	    warnInlineProtectedRoutes(routes, config.protectedRoutes, config.basePath);
132	  }
133	
134	  return [
135	    ...createRedirectRoutes(config.redirects),
136	    {
137	      element: (
138	        <Zudoku {...options} env={import.meta.env}>
139	          <BuildCheck
140	            buildId={import.meta.env.ZUPLO_BUILD_ID}
141	            environmentType={import.meta.env.ZUPLO_ENVIRONMENT_TYPE}
142	          />
143	          <Outlet />
144	        </Zudoku>
145	      ),
146	      children: [
147	        {
148	          element: (
149	            <Meta>
150	              <RouteGuard />
151	            </Meta>
152	          ),
153	          errorElement: <RouterError />,
154	          // Chunk-gate protected routes only in SSR; SSG has no 401 to avoid.
155	          children:
156	            typeof window === "undefined" || !import.meta.env.ZUDOKU_HAS_SERVER
157	              ? processRoutes(routes)
158	              : wrapProtectedRoutes(
159	                  processRoutes(routes),
160	                  config.protectedRoutes,
161	                  authState.getState().isAuthenticated,
162	                  config.basePath,
163	                ),
164	        },
165	      ],
166	    },
167	  ];
168	};
