1	import { dehydrate, QueryClient } from "@tanstack/react-query";
2	import { createHead, transformHtmlTemplate } from "@unhead/react/server";
3	import { Hono } from "hono";
4	import { compress } from "hono/compress";
5	import logger from "loglevel";
6	import { renderToReadableStream, renderToStaticMarkup } from "react-dom/server";
7	import {
8	  createStaticHandler,
9	  createStaticRouter,
10	  isRouteErrorResponse,
11	  type RouteObject,
12	} from "react-router";
13	import "vite/modulepreload-polyfill";
14	import { configuredAuthProvider } from "virtual:zudoku-auth";
15	import config from "virtual:zudoku-config";
16	import { parseCookies } from "../lib/authentication/cookies.js";
17	import { createSessionHandler } from "../lib/authentication/session-handler.js";
18	import { cachedVerifyAccessToken } from "../lib/authentication/verify-cache.js";
19	import { BootstrapStatic } from "../lib/components/Bootstrap.js";
20	import { NO_DEHYDRATE } from "../lib/components/cache.js";
21	import type { SSRAuthState } from "../lib/components/context/RenderContext.js";
22	import { ServerError } from "../lib/errors/ServerError.js";
23	import { buildManifest } from "../lib/manifest.js";
24	import { highlighterPromise } from "../lib/shiki.js";
25	import type { Adapter } from "./adapter.js";
26	import { getRoutesByConfig } from "./main.js";
27	import { protectChunks as rawProtectChunks } from "./protectChunks.js";
28	import { getSsrCacheControl } from "./ssrCacheControl.js";
29	import { wrapProtectedRoutes } from "./wrapProtectedRoutes.js";
30	
31	export { getRoutesByConfig };
32	export type { Adapter, AdapterContext } from "./adapter.js";
33	
34	// Shared cached verifier for session handler, SSR render, and protected-chunk gate.
35	const verifier = configuredAuthProvider?.verifyAccessToken
36	  ? (token: string) =>
37	      cachedVerifyAccessToken(
38	        // biome-ignore lint/style/noNonNullAssertion: verifyAccessToken is guaranteed to be defined
39	        configuredAuthProvider!.verifyAccessToken!.bind(configuredAuthProvider),
40	        token,
41	      )
42	  : undefined;
43	
44	// Wire verifier here so adapters remain auth-agnostic.
45	export const protectChunks: typeof rawProtectChunks = (opts) =>
46	  rawProtectChunks({
47	    ...opts,
48	    verifyAccessToken: opts.verifyAccessToken ?? verifier,
49	  });
50	
51	const safeSerialize = (data: unknown) =>
52	  JSON.stringify(data)
53	    .replace(/</g, "\\u003c")
54	    .replace(/>/g, "\\u003e")
55	    .replace(/\u2028/g, "\\u2028")
56	    .replace(/\u2029/g, "\\u2029");
57	
58	// Profile must come from the verifier so a forged cookie can't render
59	// protected HTML. SSG has no runtime cookie and short-circuits.
60	const resolveSsrAuth = async (
61	  request: Request,
62	): Promise<SSRAuthState | undefined> => {
63	  if (!import.meta.env.ZUDOKU_HAS_SERVER || !configuredAuthProvider) return;
64	
65	  const { accessToken } = parseCookies(request);
66	  if (!accessToken || !verifier)
67	    return { accessToken: undefined, profile: null };
68	
69	  try {
70	    const verified = await verifier(accessToken);
71	    return verified
72	      ? { accessToken, profile: verified.profile }
73	      : { accessToken: undefined, profile: null };
74	  } catch (error) {
75	    logger.error(
76	      `SSR auth verifier error (${request.method} ${request.url}):`,
77	      error,
78	    );
79	    return { accessToken: undefined, profile: null };
80	  }
81	};
82	
83	// Statically importing shiki.ts here ensures it's in the SSR bundle.
84	// main.tsx dynamically imports it instead to enable lazy loading on the client.
85	await import("virtual:zudoku-shiki-register").then(
86	  async ({ registerShiki }) => {
87	    const highlighter = await highlighterPromise;
88	    await registerShiki(highlighter);
89	  },
90	);
91	export const handleRequest = async ({
92	  template,
93	  request,
94	  routes,
95	  basePath,
96	  bypassProtection,
97	}: {
98	  template: string;
99	  request: Request;
100	  routes: RouteObject[];
101	  basePath?: string;
102	  bypassProtection?: boolean;
103	}): Promise<Response> => {
104	  const ssrAuth = await resolveSsrAuth(request);
105	
106	  // No-op lazy() on protected subtrees for unauthed requests so loaders
107	  // don't run for a 401 render.
108	  const effectiveRoutes = wrapProtectedRoutes(
109	    routes,
110	    config.protectedRoutes,
111	    !!ssrAuth?.profile,
112	    basePath,
113	  );
114	
115	  const { query, dataRoutes } = createStaticHandler(effectiveRoutes, {
116	    basename: basePath,
117	  });
118	  const queryClient = new QueryClient();
119	
120	  const context = await query(request);
121	
122	  if (context instanceof Response) {
123	    if ([301, 302, 303, 307, 308].includes(context.status)) {
124	      return new Response(null, {
125	        status: context.status,
126	        headers: { Location: context.headers.get("Location") ?? "" },
127	      });
128	    }
129	    throw context;
130	  }
131	
132	  let status = 200;
133	  if (context.errors) {
134	    const firstError = Object.values(context.errors).find(isRouteErrorResponse);
135	    if (firstError?.status) {
136	      status = firstError.status;
137	    }
138	  }
139	
140	  const router = createStaticRouter(dataRoutes, context);
141	  const head = createHead();
142	  const renderContext = {
143	    status: 200,
144	    bypassProtection: bypassProtection ?? false,
145	    ssrAuth,
146	  };
147	
148	  const App = (
149	    <BootstrapStatic
150	      router={router}
151	      context={context}
152	      queryClient={queryClient}
153	      head={head}
154	      bypassProtection={bypassProtection}
155	      renderContext={renderContext}
156	    />
157	  );
158	
159	  try {
160	    const reactStream = await renderToReadableStream(App, {
161	      onError(error) {
162	        status = 500;
163	        logger.error(`SSR Error (${request.method} ${request.url}):`, error);
164	      },
165	    });
166	
167	    await reactStream.allReady;
168	
169	    const [htmlStart, htmlEnd] = template.split("<!--app-html-->");
170	    if (!htmlStart) {
171	      throw new Error("No <!--app-html--> found in template");
172	    }
173	
174	    const headHtml = await transformHtmlTemplate(head, htmlStart);
175	
176	    const encoder = new TextEncoder();
177	    const reader = reactStream.getReader();
178	
179	    const stream = new ReadableStream<Uint8Array>({
180	      async start(controller) {
181	        controller.enqueue(encoder.encode(headHtml));
182	
183	        while (true) {
184	          const { done, value } = await reader.read();
185	          if (done) break;
186	          controller.enqueue(value);
187	        }
188	
189	        if (htmlEnd) {
190	          const dehydrated = dehydrate(queryClient, {
191	            shouldDehydrateQuery: (q) => !q.queryKey.includes(NO_DEHYDRATE),
192	          });
193	
194	          const closingTag = "</body>";
195	          const idx = htmlEnd.lastIndexOf(closingTag);
196	
197	          if (idx === -1) {
198	            controller.enqueue(encoder.encode(htmlEnd));
199	          } else {
200	            controller.enqueue(encoder.encode(htmlEnd.slice(0, idx)));
201	            const scripts = [`window.ZUDOKU_DATA=${safeSerialize(dehydrated)}`];
202	            if (ssrAuth) {
203	              scripts.push(
204	                `window.ZUDOKU_SSR_AUTH=${safeSerialize({ profile: ssrAuth.profile })}`,
205	              );
206	            }
207	            controller.enqueue(
208	              encoder.encode(`<script>${scripts.join(";")}</script>`),
209	            );
210	            controller.enqueue(encoder.encode(htmlEnd.slice(idx)));
211	          }
212	        }
213	
214	        controller.close();
215	      },
216	    });
217	
218	    const headers: HeadersInit = {
219	      "Content-Type": "text/html; charset=utf-8",
220	    };
221	    const finalStatus =
222	      renderContext.status !== 200 ? renderContext.status : status;
223	    const cacheControl = getSsrCacheControl(finalStatus, !!ssrAuth?.profile);
224	    if (cacheControl) {
225	      headers["Cache-Control"] = cacheControl;
226	    }
227	
228	    return new Response(stream, {
229	      status: finalStatus,
230	      headers,
231	    });
232	  } catch (error) {
233	    logger.error(
234	      `SSR fatal render error (${request.method} ${request.url}):`,
235	      error,
236	    );
237	    const html = renderToStaticMarkup(<ServerError error={error} />);
238	    return new Response(html, {
239	      status: 500,
240	      headers: { "Content-Type": "text/html; charset=utf-8" },
241	    });
242	  }
243	};
244	
245	export const manifest = buildManifest({
246	  basePath: config.basePath,
247	  protectedRoutes: config.protectedRoutes,
248	});
249	
250	export const createApp = () => new Hono();
251	
252	export type MountOptions<T = Hono> = {
253	  adapter?: Adapter<T>;
254	  template?: string;
255	};
256	
257	declare const __ZUDOKU_TEMPLATE__: string;
258	
259	export const mount = <T = Hono>(
260	  app: Hono,
261	  options: MountOptions<T> = {},
262	): T => {
263	  const template = options.template ?? __ZUDOKU_TEMPLATE__;
264	  const basePath = config.basePath;
265	  const routes = getRoutesByConfig(config);
266	
267	  app.use(compress());
268	  app.route(manifest.auth.sessionEndpoint, createSessionHandler(verifier));
269	  options.adapter?.setup?.(app, { basePath, manifest, protectChunks });
270	  app.all("*", (c) =>
271	    handleRequest({ template, request: c.req.raw, routes, basePath }),
272	  );
273	
274	  return (options.adapter?.finalize?.(app) ?? app) as T;
275	};
276	
277	export const createServer = <T = Hono>(options: MountOptions<T> = {}): T =>
278	  mount(createApp(), options);
