1	import type { MDXProps } from "mdx/types.js";
2	import type { JSX } from "react";
3	import type { ZudokuDocsConfig } from "../../../config/validators/ZudokuConfig.js";
4	import type { Toc } from "../../../vite/mdx/rehype-extract-toc-with-jsx.js";
5	import type { ZudokuPlugin } from "../../core/plugins.js";
6	
7	export interface MarkdownPluginOptions extends Pick<
8	  ZudokuDocsConfig,
9	  "defaultOptions" | "publishMarkdown"
10	> {
11	  basePath: string;
12	  fileImports: Record<string, () => Promise<MDXImport>>;
13	}
14	export type MarkdownPluginDefaultOptions = Pick<
15	  Frontmatter,
16	  | "toc"
17	  | "disablePager"
18	  | "showLastModified"
19	  | "suggestEdit"
20	  | "copyPage"
21	  | "fullWidth"
22	  | "centered"
23	>;
24	
25	export type Frontmatter = {
26	  title?: string;
27	  description?: string;
28	  category?: string;
29	  draft?: boolean;
30	  toc?: boolean;
31	  disablePager?: boolean;
32	  disable_pager?: boolean;
33	  showLastModified?: boolean;
34	  lastModifiedTime?: number;
35	  suggestEdit?: { url: string; text?: string } | false;
36	  copyPage?: boolean;
37	  fullWidth?: boolean;
38	  centered?: boolean;
39	};
40	
41	export type MDXImport = {
42	  tableOfContents: Toc;
43	  frontmatter: Frontmatter;
44	  excerpt?: string;
45	  __filepath: string;
46	  default: (props: MDXProps) => JSX.Element;
47	};
48	
49	export const markdownPlugin = (
50	  options: MarkdownPluginOptions,
51	): ZudokuPlugin => ({
52	  getRoutes: () => {
53	    return Object.entries(options.fileImports).map(
54	      ([routePath, importPromise]) => ({
55	        path: routePath,
56	        lazy: async () => {
57	          const { MdxPage } = await import("./MdxPage.js");
58	          const { default: Component, ...props } = await importPromise();
59	          return {
60	            element: (
61	              <MdxPage
62	                basePath={options.basePath}
63	                mdxComponent={Component}
64	                {...props}
65	                defaultOptions={options.defaultOptions}
