1	import { CirclePlayIcon } from "lucide-react";
2	import { type PropsWithChildren, Suspense, lazy } from "react";
3	import { matchPath } from "react-router";
4	import type { ZudokuPlugin } from "../../core/plugins.js";
5	import { Button } from "../../ui/Button.js";
6	import { joinUrl } from "../../util/joinUrl.js";
7	import { GraphQLClient } from "./client/GraphQLClient.js";
8	import { createQuery } from "./client/useCreateQuery.js";
9	import type { GetNavigationOperationsQuery as GetNavigationOperationsQueryResult } from "./graphql/graphql.js";
10	import { graphql } from "./graphql/index.js";
11	import type { OasPluginConfig } from "./interfaces.js";
12	import type { PlaygroundContentProps } from "./playground/Playground.js";
13	import { buildTagCategories } from "./util/buildTagCategories.js";
14	import { createNavigationCategory } from "./util/createNavigationCategory.js";
15	import { getRoutes, getVersionMetadata } from "./util/getRoutes.js";
16	import { shouldShowInfoPage } from "./util/shouldShowInfoPage.js";
17	
18	const PlaygroundDialog = lazy(() =>
19	  import("./playground/PlaygroundDialog.js").then((m) => ({
20	    default: m.PlaygroundDialog,
21	  })),
22	);
23	
24	export const GetNavigationOperationsQuery = graphql(`
25	  query GetNavigationOperations($input: JSON!, $type: SchemaType!) {
26	    schema(input: $input, type: $type) {
27	      extensions
28	      description
29	      tags {
30	        slug
31	        name
32	        extensions
33	        operations {
34	          summary
35	          slug
36	          method
37	          operationId
38	          path
39	        }
40	      }
41	      components {
42	        schemas {
43	          __typename
44	        }
45	      }
46	    }
47	  }
48	`);
49	
50	export type OperationResult =
51	  GetNavigationOperationsQueryResult["schema"]["tags"][number]["operations"][number];
52	
53	export type OpenApiPluginOptions = OasPluginConfig;
54	
55	export const UNTAGGED_PATH = "~endpoints";
56	
57	export const openApiPlugin = (config: OasPluginConfig): ZudokuPlugin => {
58	  const basePath = joinUrl(config.path);
59	  const client = new GraphQLClient(config);
60	
61	  return {
62	    getHead: () => {
63	      if (config.type === "url" && !config.skipPreload) {
64	        const urls = Array.isArray(config.input)
65	          ? config.input.map((v) => v.input)
66	          : [config.input];
67	
68	        return urls.map((url) => (
69	          <link
70	            key={url}
71	            href={url}
72	            rel="preload"
73	            as="fetch"
74	            crossOrigin="anonymous"
75	          />
76	        ));
77	      }
78	
79	      if (config.server) {
80	        return <link rel="preconnect" href={config.server} />;
81	      }
82	    },
83	    getMdxComponents: () => ({
84	      OpenPlaygroundButton: ({
85	        server,
86	        method = "get",
87	        url = "/",
88	        children,
89	        ...props
90	      }: PropsWithChildren<Partial<PlaygroundContentProps>>) => {
91	        if (!server) {
92	          throw new Error("Server is required");
93	        }
94	
95	        return (
96	          <Suspense>
97	            <PlaygroundDialog
98	              url={url}
99	              method={method}
100	              server={server}
101	              {...props}
102	            >
103	              <Button className="gap-2 items-center" variant="outline">
104	                {children ?? (
105	                  <>
106	                    Open in Playground
107	                    <CirclePlayIcon size={16} aria-hidden="true" />
108	                  </>
109	                )}
110	              </Button>
111	            </PlaygroundDialog>
112	          </Suspense>
113	        );
114	      },
115	    }),
116	    getNavigation: async (path, context) => {
117	      if (!matchPath({ path: basePath, end: false }, path)) {
118	        return [];
119	      }
120	
121	      try {
122	        const { versions } = getVersionMetadata(config);
123	
124	        const versionParam = versions.find((v) =>
125	          matchPath({ path: joinUrl(basePath, v), end: false }, path),
126	        );
127	
128	        const version = versionParam ?? versions.at(0);
129	        const { type } = config;
130	
131	        const input = Array.isArray(config.input)
132	          ? (config.input.find((v) => v.path === version)?.input ??
133	            config.input[0]?.input)
134	          : config.input;
135	
136	        const query = createQuery(client, GetNavigationOperationsQuery, {
137	          type,
138	          input,
139	        });
140	        const data = await context.queryClient.ensureQueryData(query);
141	
142	        const tagCategories = new Map(
143	          data.schema.tags
144	            .filter((tag) => tag.name && tag.operations.length > 0)
145	            .map((tag) => {
146	              if (!tag.name) {
147	                throw new Error(`Tag ${tag.slug} has no name`);
148	              }
149	
150	              const categoryPath = joinUrl(basePath, versionParam, tag.slug);
151	
152	              const isCollapsed =
153	                tag.extensions?.["x-zudoku-collapsed"] ??
154	                !config.options?.expandAllTags;
155	              const isCollapsible =
156	                tag.extensions?.["x-zudoku-collapsible"] ?? true;
157	
158	              return [
159	                tag.name,
160	                createNavigationCategory({
161	                  label: tag.extensions?.["x-displayName"] ?? tag.name,
162	                  path: categoryPath,
163	                  operations: tag.operations,
164	                  collapsed: isCollapsed,
165	                  collapsible: isCollapsible,
166	                }),
167	              ];
168	            }),
169	        );
170	
171	        const tagGroups =
172	          (data.schema.extensions?.["x-tagGroups"] as
173	            | { name: string; tags: string[] }[]
174	            | undefined) ?? [];
175	
176	        const categories = buildTagCategories({
177	          tagCategories,
178	          tagGroups,
179	          expandAllTags: config.options?.expandAllTags,
180	        });
181	
182	        if (
183	          shouldShowInfoPage(
184	            config.options?.showInfoPage,
185	            !!data.schema.description,
186	          )
187	        ) {
188	          categories.unshift({
189	            type: "link" as const,
190	            to: joinUrl(basePath, versionParam),
191	            label: "Information",
192	          });
193	        }
194	
195	        const untaggedOperations = data.schema.tags.find(
196	          (tag) => !tag.name,
197	        )?.operations;
198	
199	        if (untaggedOperations && untaggedOperations.length > 0) {
200	          categories.push(
201	            createNavigationCategory({
202	              label: categories.length === 0 ? "Endpoints" : "Other endpoints",
203	              path: joinUrl(basePath, versionParam, UNTAGGED_PATH),
204	              operations: untaggedOperations,
205	              collapsed: !config.options?.expandAllTags,
206	            }),
207	          );
208	        }
209	
210	        if (data.schema.components?.schemas?.length) {
211	          categories.push({
212	            type: "link",
213	            label: "Schemas",
214	            to: joinUrl(basePath, versionParam, "~schemas"),
215	          });
216	        }
217	
218	        return categories;
219	      } catch {
220	        return [];
221	      }
222	    },
223	    getRoutes: () => getRoutes({ basePath, config, client }),
224	  };
225	};
