80	const createZuploService = ({
81	  deploymentName,
82	  ...options
83	}: DefaultApiKeyServiceOptions): ApiKeyService => {
84	  return {
85	    deleteKey: async (consumerId, keyId, context) => {
86	      invariant(deploymentName, "Cannot delete API key.", developerHintOptions);
87	      const request = new Request(
88	        joinUrl(
89	          getApiKeyEndpoint(context),
90	          `${deploymentName}/consumers/${consumerId}/keys/${keyId}`,
91	        ),
92	        {
93	          method: "DELETE",
94	        },
95	      );
96	      const response = await fetch(await context.signRequest(request));
97	      await throwIfProblemJson(response);
98	      invariant(response.ok, "Failed to delete API key");
99	    },
100	    updateConsumer: async (consumer, context) => {
101	      invariant(
102	        deploymentName,
103	        "Cannot update API key description.",
104	        developerHintOptions,
105	      );
106	      const response = await fetch(
107	        await context.signRequest(
108	          new Request(
109	            joinUrl(
110	              getApiKeyEndpoint(context),
111	              `${deploymentName}/consumers/${consumer.id}`,
112	            ),
113	            {
114	              method: "PATCH",
115	              headers: {
116	                "Content-Type": "application/json",
117	              },
118	              body: JSON.stringify({
119	                label: consumer.label,
120	              }),
121	            },
122	          ),
123	        ),
124	      );
125	      await throwIfProblemJson(response);
126	      invariant(response.ok, "Failed to update API key description");
127	    },
128	    rollKey: async (consumerId, context) => {
129	      invariant(deploymentName, "Cannot roll API key.", developerHintOptions);
130	      const response = await fetch(
131	        await context.signRequest(
132	          new Request(
133	            joinUrl(
134	              getApiKeyEndpoint(context),
135	              `${deploymentName}/consumers/${consumerId}/roll-key`,
136	            ),
137	            {
138	              method: "POST",
139	              headers: {
140	                "Content-Type": "application/json",
141	              },
142	              body: JSON.stringify({}),
143	            },
144	          ),
145	        ),
146	      );
147	      await throwIfProblemJson(response);
148	      invariant(response.ok, "Failed to roll API key");
149	    },
150	    getConsumers: async (context) => {
151	      invariant(deploymentName, "Cannot get API keys.", developerHintOptions);
152	      const request = new Request(
153	        joinUrl(getApiKeyEndpoint(context), `${deploymentName}/consumers`),
154	      );
155	      await context.signRequest(request);
156	
157	      const keys = await fetch(request);
158	      await throwIfProblemJson(keys);
159	      invariant(keys.ok, "Failed to fetch API keys");
160	
161	      const data = (await keys.json()) as {
162	        data: [
163	          {
164	            id: string;
165	            label?: string;
166	            subject?: string;
167	            createdOn?: string;
168	            updatedOn?: string;
169	            expiresOn?: string;
170	            apiKeys: {
171	              data: ApiKey[];
172	            };
173	          },
174	        ];
175	      };
176	
177	      return data.data.map((consumer) => ({
178	        id: consumer.id,
179	        createdOn: consumer.createdOn,
180	        updatedOn: consumer.updatedOn,
181	        expiresOn: consumer.expiresOn,
182	        label: consumer.label || consumer.subject || "API Key",
183	        apiKeys: consumer.apiKeys.data,
184	        key: consumer.apiKeys.data.at(0),
185	      }));
186	    },
187	    ...options,
188	  };
189	};
