191	export const createApiKeyService = <T extends ApiKeyService>(service: T): T =>
192	  service;
193	
194	type InternalApiKeyPluginOptions = {
195	  // The name of the Zuplo deployment
196	  deploymentName?: string;
197	  // Indicates that the plugin is running in Zuplo "mode"
198	  isZuplo?: boolean;
199	};
200	
201	export const apiKeyPlugin = ({
202	  deploymentName,
203	  isZuplo,
204	  ...options
205	}: Omit<ApiKeysOptions, "enabled"> &
206	  InternalApiKeyPluginOptions): ZudokuPlugin &
207	  ApiIdentityPlugin &
208	  ProfileMenuPlugin => {
209	  if (isZuplo && !deploymentName) {
210	    // biome-ignore lint/suspicious/noConsole: Important warning
211	    console.warn(
212	      "This project is not linked to a Zuplo deployment. Run `zuplo link` to get started.",
213	    );
214	  }
215	
216	  const service = isZuplo
217	    ? createZuploService({ deploymentName, ...options })
218	    : options;
219	
220	  if (!service.getConsumers) {
221	    throw new Error("getConsumers is required when using the apiKeyPlugin");
222	  }
223	
224	  const verifiedService: ApiKeyService = {
225	    ...service,
226	    getConsumers: service.getConsumers,
227	  };
228	
229	  return {
230	    getProfileMenuItems: () => [
231	      {
232	        label: "API Keys",
233	        path: "/settings/api-keys",
234	        category: "middle",
235	        icon: KeyRoundIcon,
236	      },
237	    ],
238	
239	    getIdentities: async (context) => {
240	      try {
241	        const consumers = await verifiedService.getConsumers(context);
242	
243	        return consumers.map((consumer) => ({
244	          authorizeRequest: (request) => {
245	            request.headers.set(
246	              "Authorization",
247	              `Bearer ${consumer.apiKeys.at(0)?.key}`,
248	            );
249	            return request;
250	          },
251	          authorizationFields: { headers: ["Authorization"] },
252	          id: consumer.id,
253	          label: consumer.label,
254	        }));
255	      } catch {
256	        return [];
257	      }
258	    },
259	
260	    getRoutes: (): RouteObject[] => {
261	      return [
262	        {
263	          path: "/settings/api-keys",
264	          element: <SettingsApiKeys service={verifiedService} />,
265	        },
266	      ];
267	    },
268	
269	    getProtectedRoutes: () => {
270	      return ["/settings/api-keys"];
271	    },
272	  };
273	};
