138	const createVersionRoutes = ({
139	  versionPath,
140	  tagPages,
141	  hasUntaggedOperations = true,
142	  showInfoPage,
143	}: {
144	  versionPath: string;
145	  tagPages: string[];
146	  hasUntaggedOperations?: boolean;
147	  showInfoPage?: boolean;
148	}): RouteObject[] => {
149	  const firstTag =
150	    tagPages.at(0) ?? (hasUntaggedOperations ? UNTAGGED_PATH : undefined);
151	  const redirectTo = firstTag ? joinUrl(versionPath, firstTag) : undefined;
152	
153	  // When showInfoPage is explicitly false, skip the info page and redirect to
154	  // the first tag. Otherwise render the info page, which decides at runtime
155	  // whether to show itself — it hides when there is no API description, unless
156	  // showInfoPage is explicitly true.
157	  const indexRoute: RouteObject =
158	    showInfoPage === false
159	      ? redirectTo
160	        ? { index: true, loader: () => redirect(redirectTo) }
161	        : createRoute({ path: versionPath })
162	      : {
163	          index: true,
164	          path: versionPath,
165	          lazy: async () => {
166	            const { SchemaInfo } = await import("../SchemaInfo.js");
167	            return {
168	              element: (
169	                <SchemaInfo
170	                  showInfoPage={showInfoPage}
171	                  redirectTo={redirectTo}
172	                />
173	              ),
174	            };
175	          },
176	        };
177	
178	  return [
179	    indexRoute,
180	    ...tagPages.map((tag) =>
181	      createRoute({ path: joinUrl(versionPath, tag), tag }),
182	    ),
183	    ...createAdditionalRoutes({ basePath: versionPath, hasUntaggedOperations }),
184	  ];
185	};
