187	export const getVersionMetadata = (config: OasPluginConfig) => {
188	  if (config.type === "raw" || !Array.isArray(config.input)) {
189	    return {
190	      versions: [] as string[],
191	      versionMap: {} as Record<
192	        string,
193	        { label: string; downloadUrl?: string; tagPages?: string[] }
194	      >,
195	    };
196	  }
197	
198	  return {
199	    versions: config.input.map((v) => v.path),
200	    versionMap: Object.fromEntries(
201	      config.input.map((v) => [
202	        v.path,
203	        {
204	          label: v.label ?? v.path,
205	          downloadUrl: v.downloadUrl,
206	          tagPages: v.tagPages,
207	        },
208	      ]),
209	    ),
210	  };
211	};
212	
213	/**
214	 * Build the target URL when switching versions. Preserves the current tag
215	 * if it exists in the target version, otherwise navigates to the version
216	 * root (which redirects to its first tag).
217	 */
218	export const buildVersionSwitchUrl = (
219	  target: VersionEntry,
220	  currentTag: string | undefined,
221	) => {
222	  const tagExistsInTarget =
223	    currentTag && (!target.tagPages || target.tagPages.includes(currentTag));
224	
225	  if (!tagExistsInTarget) return target.path;
226	
227	  return joinUrl(target.path, currentTag);
228	};
