230	export const getRoutes = ({
231	  basePath,
232	  config,
233	  client,
234	}: {
235	  client: GraphQLClient;
236	  config: OpenApiPluginOptions;
237	  basePath: string;
238	}): RouteObject[] => {
239	  const tagPages = config.tagPages;
240	  const { versions } = getVersionMetadata(config);
241	  const inputArray = Array.isArray(config.input) ? config.input : undefined;
242	
243	  // undefined entry = index path that serves the latest version
244	  const versionsInPath =
245	    versions.length > 1 ? [undefined, ...versions] : [undefined];
246	
247	  return versionsInPath.map((version) => {
248	    const versionPath = joinUrl(basePath, version);
249	    const versionInput = version
250	      ? inputArray?.find((v) => v.path === version)
251	      : inputArray?.[0];
252	    const hasUntaggedOperations = versionInput?.hasUntaggedOperations ?? true;
253	
254	    const versionTagPages = versionInput?.tagPages ?? tagPages;
255	
256	    return createOasProvider({
257	      basePath,
258	      version,
259	      routePath: versionPath,
260	      routes: versionTagPages
261	        ? createVersionRoutes({
262	            versionPath,
263	            tagPages: versionTagPages,
264	            hasUntaggedOperations,
265	            showInfoPage: config.options?.showInfoPage,
266	          })
267	        : [
268	            createNonTagPagesRoute({ path: `${versionPath}/:tag?` }),
269	            ...createAdditionalRoutes({
270	              basePath: versionPath,
271	              hasUntaggedOperations,
272	            }),
273	          ],
274	      client,
275	      config,
276	    });
277	  });
278	};
