45	      };
46	    case 500:
47	      return {
48	        title: "Internal Server Error",
49	        message: "An unexpected error occurred while processing your request.",
50	      };
51	    case 501:
52	      return {
53	        title: "Not Implemented",
54	        message:
55	          "The server does not support the functionality required to fulfill the request.",
