62	      };
63	    case 503:
64	      return {
65	        title: "Service Unavailable",
66	        message: "The server is temporarily unable to handle the request.",
67	      };
68	    case 504:
69	      return {
70	        title: "Gateway Timeout",
71	        message:
72	          "The server did not receive a timely response from the upstream server.",
73	      };
74	    default:
75	      return {
76	        title: "An error occurred",
77	        message: "Something went wrong while processing your request.",
78	      };
79	  }
80	};
81	
82	export const StatusPage = ({ statusCode, message }: StatusPageProps) => {
83	  if (statusCode === 404) {
84	    return <NotFoundPage />;
85	  }
86	
87	  const defaultContent = getDefaultContent(statusCode);
88	
89	  return (
90	    <ErrorPage
91	      title={defaultContent.title}
92	      message={message ?? defaultContent.message}
93	      category={statusCode}
94	    />
95	  );
