  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();

  async function explore(url) {
    try {
      await page.goto('http://localhost:4321' + url, { waitUntil: 'networkidle', timeout: 15000 });
      const title = await page.title();
      const currentUrl = page.url().replace('http://localhost:4321','');
      const h1s = await page.\$\$eval('h1,h2', els => els.map(e=>e.textContent.trim().substring(0,80)).filter(t=>t)).catch(()=>[]);
      const links = await page.\$\$eval('a[href]', els => [...new Set(els.map(e=>e.getAttribute('href')))].filter(h=>h&&h.startsWith('/'))).catch(()=>[]);
      const buttons = await page.\$\$eval('button', els => els.map(e=>e.textContent.trim().substring(0,50)).filter(t=>t)).catch(()=>[]);
      const selects = await page.\$\$eval('select,[role=combobox]', els => els.map(e=>e.getAttribute('aria-label')||e.textContent.trim().substring(0,40))).catch(()=>[]);
      return { url, currentUrl, title, h1s: h1s.slice(0,5), links: [...new Set(links)].slice(0,25), buttons: buttons.slice(0,15), selects: selects.slice(0,8) };
    } catch(e) { return { url, error: e.message.substring(0,100) }; }
  }

  const pages = [
    '/status', '/documentation/test',
    '/catalog/api-cargo-containers/containers', '/catalog/api-cargo-containers/booking', '/catalog/api-cargo-containers/quotes',
    '/catalog/api-fleet-ops/fleet-command', '/catalog/api-fleet-ops/navigation',
    '/catalog/api-docs/documentation', '/catalog/api-ai-cargo/~schemas',
    '/catalog/api-label/latest', '/catalog/api-fleet-ops/v1/fleet-command', '/catalog/api-fleet-ops/v2/fleet-command',
    '/member-benefits', '/premium-fleet-services',
    '/400', '/404', '/500', '/notfound-random'
  ];
  const results = {};
  for (const p of pages) {
    results[p] = await explore(p);
  }
  console.log(JSON.stringify(results, null, 2));
  await browser.close();
})().catch(e=>console.error(e))
" 2>&1

